import {researchTreeView,bindResearchTree} from './research-tree.js';
import {bindIntelligenceSearch} from './technology-actions.js';
import {escapeHtml as h,number} from './domain.js';
import {planetArt} from './art.js';
const errorBox='<p class="form-error" role="alert" hidden></p>';
const money=n=>number(n)+' Þ';
const date=n=>new Date(n).toLocaleString('fr-FR',{dateStyle:'short',timeStyle:'short'});
export function energyQuote(capacity,quantity,prices){const q=Number(quantity);if(!Number.isInteger(q)||q<1||q>100-capacity)return null;let cost=0;for(let i=capacity+1;i<=capacity+q;i++){if(!Number.isFinite(Number(prices[i])))return null;cost+=Number(prices[i]);}return cost;}
export function teleportDestinations(targets,origin,query=''){
 if(!origin)return [];const term=query.trim().toLocaleLowerCase('fr');
 return targets.filter(p=>p.id!==origin.id&&(origin.is_own||p.is_own)&&(!term||p.name.toLocaleLowerCase('fr').includes(term))).map(p=>({...p,distance:Math.hypot(p.x-origin.x,p.y-origin.y)})).sort((a,b)=>a.distance-b.distance).slice(0,15);
}
export function teleportQuote(origin,target,quantity,now=Date.now(),capacity=5){
 const q=Number(quantity);if(!origin||!target||!Number.isInteger(q)||q<1)return null;
 const cost=origin.is_own&&target.is_own?Math.ceil(q/(2*capacity)):Math.ceil(q/capacity),bank=origin.is_own?origin:target;
 return {cost,bank:bank.name,needsPassword:(origin.is_own?target:origin).access==='password',valid:q<=origin.available_soldiers&&cost<=Number(bank.energy)&&new Date(origin.network_ready_at).getTime()<=now&&new Date(target.network_ready_at).getTime()<=now};
}
export function technologiesView(data,treasury,originId,pending,researchPlanet){
 if(!data)return '<p class="empty">Synchronisation des recherches…</p>';
 const origin=data.origins.find(p=>p.id===originId)||data.origins[0];
 return `<div class="technology-page">${pending?`<form id="resume-technology" class="document-panel"><h3>Commande en attente</h3>${pending.secret_required?'<label class="field">Saisir à nouveau le code d’accès<input name="password" type="password" maxlength="72" autocomplete="off" required></label>':''}${errorBox}<button class="secondary" type="submit">Reprendre la commande</button></form>`:''}${researchTreeView(data,treasury,researchPlanet)}
 <details class="energy-reserves"><summary><h2>Réserves énergétiques</h2><span>STOCKAGE LOCAL</span></summary><div class="energy-worlds">${data.planets.map(p=>`<article class="document-panel energy-world"><header><img src="${planetArt(p.race+'_'+p.resource,true)}" alt="" width="72" height="72"><div><h3>${h(p.name)}</h3><strong>${p.energy} <small>/ ${p.energy_max} charges</small></strong></div></header><progress max="${p.energy_max}" value="${p.energy}" aria-label="Énergie de ${h(p.name)}"></progress><p>${!data.energy_unlocked?'Recharge verrouillée.':p.next_recharge_at?`Prochaine charge : ${date(p.next_recharge_at)}`:'Réserve pleine.'}</p>${data.energy_unlocked&&p.energy_max<(data.storage_limit||10)?`<form data-technology="energy_capacity" data-planet="${h(p.id)}" data-capacity="${p.energy_max}"><input type="hidden" name="expected_capacity" value="${p.energy_max}"><label class="field">Places à ajouter<input type="number" name="quantity" min="1" max="${(data.storage_limit||10)-p.energy_max}" step="1" value="1" required></label><strong data-energy-quote>${money(data.energy_prices[p.energy_max+1])}</strong><button class="secondary" type="submit">Agrandir la réserve →</button>${errorBox}</form>`:''}${data.teleport_unlocked?`<div class="planet-teleport-code"><h4>Accès à la téléportation</h4><p>${new Date(p.teleport_ready_at)>new Date(data.server_now)?`Connexion au réseau : ${date(p.teleport_ready_at)}`:'Planète connectée au réseau.'}</p><p>${p.code_configured?'Un code est défini.':'Accès réservé à vous et à votre clan.'}</p><form data-technology="password" data-planet="${h(p.id)}"><label class="field">Nouveau code d’accès<input name="password" type="password" minlength="8" maxlength="72" autocomplete="off" required></label>${errorBox}<button class="secondary" type="submit">${p.code_configured?'Remplacer':'Définir'} le code</button></form>${p.code_configured?`<form data-technology="password" data-planet="${h(p.id)}"><input type="hidden" name="password" value="">${errorBox}<button class="text-button" type="submit">Retirer le code</button></form>`:''}</div>`:''}</article>`).join('')}</div></details>
 ${data.teleport_unlocked?`<section class="document-panel teleport-console"><div class="eyebrow">RÉSEAU INSTANTANÉ</div><h2>Téléporter des soldats</h2><form data-technology="teleport"><label class="field">Origine<select name="origin_id" id="teleport-origin">${data.origins.map(p=>`<option value="${h(p.id)}" ${p.id===origin?.id?'selected':''}>${h(p.name)} · ${number(p.available_soldiers)} soldats au sol</option>`).join('')}</select></label><label class="field">Rechercher une destination<input id="teleport-search" type="search" placeholder="Nom de la planète" autocomplete="off"></label><label class="field">Destination<select name="target_id" id="teleport-target" required></select></label><label class="field">Soldats à téléporter<input name="quantity" type="number" min="1" step="1" value="1" required></label><label class="field" id="teleport-code-field" hidden>Code d’accès de la planète étrangère<input name="password" type="password" maxlength="72" autocomplete="off"></label><p class="teleport-estimate" id="teleport-estimate" aria-live="polite"></p>${errorBox}<button class="primary" type="submit" ${!data.energy_unlocked?'disabled':''}>Téléporter les soldats →</button></form></section>`:''}</div>`;
}
export function bindTechnologies({db,state,render,loadPlayer,submit,toast}){
 const data=state.technologies;if(!data)return;bindResearchTree(state,render);bindIntelligenceSearch(data);
 const key='lw-technology-command:'+state.user.id;
 const pending=()=>{try{return JSON.parse(sessionStorage.getItem(key)||'null');}catch{return null;}};
 const send=async(action,args,existing)=>{
  const {password,...safeArgs}=args,secret=password||'',payload={action,args:safeArgs};let p=existing||pending();
  if(p&&JSON.stringify(p.payload)!==JSON.stringify(payload))throw Error('Reprenez d’abord la commande en attente.');
  p||={id:crypto.randomUUID(),payload,secret_required:!!secret};sessionStorage.setItem(key,JSON.stringify(p));
  const intel=['infiltrate','security','purify','purify_cancel','infiltration_cancel','infiltration_target','drain'],special=['camouflage','massive_bombing','stasis','scan','gate_connect','gate_disconnect','gate_jump','black_hole_prepare','black_hole_cancel','black_hole_activate','energy_blast'];
  const api=intel.includes(action)?'intelligence_command':special.includes(action)?'special_command':'technology_command';
  const {data:result,error}=await db.rpc(api,{p_action:action,p_args:{...safeArgs,...(password!==undefined?{password:secret}:{})},p_request_id:p.id});
  if(error){if(error.code)sessionStorage.removeItem(key);throw error;}
  sessionStorage.removeItem(key);if(result.ok===false)throw Error(result.error);
  await loadPlayer();toast(action==='teleport'?'Soldats téléportés.':action==='research'?'Recherche lancée.':action==='research_cancel'?'Recherche annulée et remboursée.':action==='password'?'Accès planétaire mis à jour.':action==='energy_capacity'?'Réserve agrandie.':'Ordre confirmé.');
 };
 document.querySelectorAll('form[data-technology]').forEach(form=>form.addEventListener('submit',event=>{event.preventDefault();submit(form,async fields=>{const args=Object.fromEntries(fields);if(form.dataset.planet)args.planet_id=form.dataset.planet;for(const k of ['quantity','expected_capacity','expected_level','target_level','accuracy','rate','energy'])if(k in args)args[k]=Number(args[k]);if(form.dataset.destructive&&!window.confirm('Cette action détruit définitivement la planète et les forces concernées. Confirmer l’activation ?'))return;await send(form.dataset.technology,args);});}));
 document.querySelector('#resume-technology')?.addEventListener('submit',event=>{event.preventDefault();submit(event.currentTarget,async fields=>{const p=pending();if(p)await send(p.payload.action,{...p.payload.args,...(p.secret_required?{password:fields.get('password')}:{})},p);});});
 document.querySelectorAll('[data-technology="energy_capacity"]').forEach(form=>form.addEventListener('input',()=>{const quote=energyQuote(Number(form.dataset.capacity),form.elements.quantity.value,data.energy_prices);form.querySelector('[data-energy-quote]').textContent=quote===null?'Quantité invalide':money(quote);form.querySelector('button').disabled=quote===null||quote>state.empire.treasury;}));
 const form=document.querySelector('[data-technology="teleport"]');
 if(form){let targets=[];const estimate=()=>{const origin=data.origins.find(p=>p.id===form.elements.origin_id.value),target=targets.find(p=>p.id===form.elements.target_id.value),quote=teleportQuote(origin,target,form.elements.quantity.value,Date.now(),data.teleport_capacity||1);form.elements.quantity.max=String(origin?.available_soldiers||0);
  const label=form.querySelector('#teleport-code-field');label.hidden=!quote?.needsPassword;form.elements.password.required=!!quote?.needsPassword;if(label.hidden)form.elements.password.value='';
  form.querySelector('#teleport-estimate').textContent=!data.energy_unlocked?'La recharge d’énergie doit être débloquée.':!quote?'Choisissez une destination.':`${quote.cost} charge${quote.cost>1?'s':''} sur ${quote.bank} · ${number(origin.available_soldiers)} soldats disponibles${quote.valid?'':' · Vérifiez les soldats, l’énergie et la connexion au réseau.'}`;
  form.querySelector('[type=submit]').disabled=!data.energy_unlocked||!quote?.valid;
 };const destinations=()=>{const origin=data.origins.find(p=>p.id===form.elements.origin_id.value);state.technologyOrigin=origin?.id;targets=teleportDestinations(data.targets,origin,form.querySelector('#teleport-search').value);form.elements.target_id.innerHTML=targets.map(p=>`<option value="${h(p.id)}">${h(p.name)} · ${p.access==='own'?'Votre planète':p.access==='clan'?'Clan':p.access==='infiltration'?'Infiltration':'Code d’accès'}</option>`).join('');estimate();};form.elements.origin_id.onchange=destinations;form.querySelector('#teleport-search').oninput=destinations;form.elements.target_id.onchange=estimate;form.elements.quantity.oninput=estimate;destinations();}
 document.querySelector('[data-teleport-console]')?.addEventListener('click',()=>document.querySelector('.teleport-console')?.scrollIntoView({behavior:'smooth',block:'start'}));
 document.querySelectorAll('[data-open-technology]').forEach(button=>button.onclick=()=>{state.page='research';render();});
}
export function readTechnologyPending(userId){try{return JSON.parse(sessionStorage.getItem('lw-technology-command:'+userId)||'null');}catch{return null;}}
